const C=window.CURRICULUM, app=document.querySelector('#app');
const KEY='actMasteryPathway_v7';
const OLD_KEYS=['actMasteryPathway_v5','actMasteryPathway_v4','actMasteryPathway_v3','actMathPathways_v2','actMathPathways_v1'];
const STAFF_PIN='27610';
let S=JSON.parse(localStorage.getItem(KEY)||OLD_KEYS.map(k=>localStorage.getItem(k)).find(Boolean)||'null')||{name:'',view:'home',diag:null,mastered:{},module:{},post:null,seed:11,achievements:{},bookmarks:[],activity:[],settings:{reducedMotion:false}};
if(!localStorage.getItem(KEY) && S.run && ['practice','mini','post'].includes(S.run.type)) delete S.run;
const save=()=>localStorage.setItem(KEY,JSON.stringify(S));
const esc=s=>String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const sub=id=>C.subtopics.find(x=>x.id===id);
const shuffle=(a,r=Math.random)=>{a=[...a];for(let i=a.length-1;i;i--){let j=Math.floor(r()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a};
function rng(seed){return()=>((seed=Math.imul(1664525,seed)+1013904223|0)>>>0)/4294967296}
function domainStats(){let out={};C.subtopics.forEach(x=>{out[x.domain]??={n:0,m:0,c:0,q:0};out[x.domain].n++;out[x.domain].m+=!!S.mastered[x.id];let d=S.diag?.bySub?.[x.id];if(d){out[x.domain].c+=d.c;out[x.domain].q+=d.n}});return out}
function recommended(){if(!S.diag)return null;return C.subtopics.filter(x=>!S.mastered[x.id]).sort((a,b)=>{let A=S.diag.bySub[a.id],B=S.diag.bySub[b.id];return (A.c/A.n)-(B.c/B.n)})[0]||null}
function shell(body){app.innerHTML=`<main class="shell"><div class="top no-print"><button class="brandButton" onclick="go('home')" aria-label="ACT Mastery Pathway home"><span class="brandMain">ACT MASTERY</span><span class="brandSub">PATHWAY</span></button><nav class="row nav" aria-label="Primary navigation"><button class="navBtn" onclick="go('home')">Dashboard</button><button class="navBtn" onclick="go('course')">Course Map</button><button class="navBtn" onclick="resources()">Toolkit</button><button class="navBtn" onclick="studyPlan()">Study Plan</button><button class="navBtn" onclick="showDataTools()">Save / Load</button><button class="navBtn staff" onclick="unlockInstructor()" title="Staff access">Staff Access</button></nav></div>${body}<footer class="footer no-print">ACT Mastery Pathway • Independent ACT-style instructional curriculum • Scores are instructional indicators, not official ACT scores.</footer></main>`;window.scrollTo(0,0)}
function unlockInstructor(){if(sessionStorage.getItem('ampStaff')==='1'){S.view='instructor';save();return render()}const pin=prompt('Enter the staff PIN:');if(pin===null)return;if(pin===STAFF_PIN){sessionStorage.setItem('ampStaff','1');S.view='instructor';save();render()}else alert('Incorrect PIN.')} 
function go(v){S.view=v;save();render()}
function home(){
 let done=C.subtopics.filter(x=>S.mastered[x.id]).length, diag=!!S.diag, all=done===C.subtopics.length, rec=recommended();
 let pct=Math.round(done/C.subtopics.length*100);
 shell(`<section class="card hero premium"><div class="eyebrow">PERSONALIZED • MASTERY-BASED • ACT-STYLE</div><div class="heroGrid"><div><div class="confetti"></div><h1>Build the math skills.<br><span>Know the strategy.</span></h1><p class="sub">Diagnostic results identify what to study next. Complete targeted lessons, demonstrate mastery, and measure growth on the post-assessment.</p><div class="row"><input class="nameinput" placeholder="Student name" value="${esc(S.name)}" oninput="S.name=this.value;save()"><span class="pill">${done}/15 subtopics mastered</span></div></div><div class="progressPanel"><div class="ring" style="--p:${pct}"><b>${pct}%</b><span>pathway complete</span></div>${diag?`<div class="miniStat"><b>${S.diag.score}/45</b><span>diagnostic</span></div>`:`<div class="miniStat"><b>45</b><span>diagnostic items</span></div>`}${S.post?`<div class="miniStat"><b>${S.post.score}/45</b><span>post-test</span></div>`:`<div class="miniStat"><b>15</b><span>skill modules</span></div>`}</div></div></section>
 <section class="card"><h2>Your pathway</h2><div class="path"><span class="${diag?'done':'active'}">1. Diagnostic</span><span class="${diag&&!all?'active':all?'done':''}">2. Personalized modules</span><span class="${all&&!S.post?'active':S.post?'done':''}">3. Post-assessment</span><span class="${S.post?'active':''}">4. Growth report</span></div>${rec?`<div class="recommend"><div><b>Recommended next:</b> ${esc(rec.name)}<div class="tiny">Based on your lowest unmastered diagnostic subtopic.</div></div><button class="btn" onclick="openModule('${rec.id}')">Continue →</button></div>`:''}</section>
 <section class="grid featureGrid">
 <div class="card"><div class="icon"></div><h3>Diagnostic</h3><p class="sub">45 original ACT-style questions • 50 minutes • balanced across 15 subtopics.</p>${S.diag?`<p><b>${S.diag.score}/45</b> correct</p><button class="btn secondary" onclick="startTest('diag',true)">Retake diagnostic</button>`:`<button class="btn" onclick="startTest('diag')">Begin diagnostic</button>`}</div>
 <div class="card"><div class="icon"></div><h3>Personalized learning path</h3><p class="sub">Skills demonstrated on the diagnostic are marked complete. Remaining topics become focused lessons with strategy-first practice.</p><button class="btn" ${diag?'':'disabled'} onclick="go('modules')">Open my modules</button></div>
 <div class="card"><div class="icon"></div><h3>Post-assessment</h3><p class="sub">A parallel 45-question form measures transfer after all modules are mastered.</p><button class="btn" ${all?'':'disabled'} onclick="startTest('post')">${S.post?'Retake':'Begin'} post-assessment</button></div>
 <div class="card"><div class="icon"></div><h3>Mastery report</h3><p class="sub">Printable diagnostic-to-post growth with subtopic-level evidence.</p><button class="btn secondary" onclick="report()">View report</button></div></section>
 <section class="grid featureGrid"><div class="card"><div class="icon"></div><h3>Study plan</h3><p class="sub">Turn diagnostic data into a prioritized week-by-week plan with estimated module time.</p><button class="btn secondary" onclick="studyPlan()">Build my plan</button></div><div class="card"><div class="icon"></div><h3>Math toolkit</h3><p class="sub">ACT-focused formulas, vocabulary, test-day habits, and quick-reference strategy cards.</p><button class="btn secondary" onclick="resources()">Open toolkit</button></div><div class="card"><div class="icon"></div><h3>Completion certificate</h3><p class="sub">After the post-assessment, print a polished record of curriculum completion and growth.</p><button class="btn secondary" ${S.post?'':'disabled'} onclick="certificate()">View certificate</button></div></section>
 <section class="card"><div class="row"><div><div class="eyebrow">WHAT MAKES THIS DIFFERENT</div><h2>Strategy is assessed before computation.</h2></div></div><div class="grid"><div class="callout"><b>1 • Recognize</b><span>Students identify the mathematical approach.</span></div><div class="callout"><b>2 • Reason</b><span>Feedback corrects misconceptions without revealing the answer.</span></div><div class="callout"><b>3 • Execute</b><span>Students independently solve the ACT-style problem.</span></div><div class="callout"><b>4 • Prove mastery</b><span>A 5-item unscaffolded check requires 80%.</span></div></div></section>`)
}
function courseMap(){let groups={};C.subtopics.forEach(x=>(groups[x.domain]??=[]).push(x));let html=Object.entries(groups).map(([d,xs])=>`<section class="card"><div class="row"><h2>${esc(d)}</h2><span class="spacer"></span><span class="pill">${xs.filter(x=>S.mastered[x.id]).length}/${xs.length} mastered</span></div><div class="curriculumList">${xs.map((x,i)=>`<button class="curriculumRow" onclick="${S.diag?`openModule('${x.id}')`:`go('home')`}"><span class="num">${String(i+1).padStart(2,'0')}</span><span><b>${esc(x.name)}</b><small>${esc(x.desc)}</small></span><span>${S.mastered[x.id]?'✓':'→'}</span></button>`).join('')}</div></section>`).join('');shell(`<section class="card"><div class="eyebrow">SCOPE & SEQUENCE</div><h1>ACT Math Course Map</h1><p class="sub">Fifteen measurable subtopics organized into a focused sequence. Diagnostic mastery allows students to move past content they can already demonstrate independently.</p></section>${html}`)}
function modules(){
 if(!S.diag)return go('home');
 let cards=C.subtopics.map((x,i)=>{let m=S.mastered[x.id], ds=S.diag.bySub[x.id]||{c:0,n:3}, ms=S.module[x.id]||{};let status=m?'mastered':ms.practiceDone?'assessment ready':'instruction';return `<div class="card module ${m?'mastered':''}"><div class="row"><span class="tag">${esc(x.domain)}</span><span class="spacer"></span><span class="status ${status}">${m?'✓ Mastered':ms.practiceDone?'Ready to prove':'Learn'}</span></div><h3>${esc(x.name)}</h3><p class="sub">${esc(x.desc)}</p><div class="skillMeter"><i style="width:${ds.c/ds.n*100}%"></i></div><p class="tiny">Diagnostic evidence: ${ds.c}/${ds.n} • ${m&&ms.source==='diagnostic'?'compacted from diagnostic':ms.attempts?`best mastery check ${ms.best}/5`:'module assigned'}</p><button class="btn ${m?'secondary':''}" onclick="openModule('${x.id}')">${m?'Review':'Open module'} →</button></div>`}).join('');
 shell(`<section class="card"><div class="eyebrow">YOUR PERSONALIZED PLAN</div><h1>Mastery modules</h1><p class="sub">Green modules are complete. Unfinished modules move from explicit modeling to guided strategy practice and finally to an unscaffolded five-question mastery check.</p><div class="legend"><span>Learn</span><span>Assessment ready</span><span>✓ Mastered</span></div></section><section class="grid">${cards}</section>`)
}
function openModule(id){S.current=id;S.view='module';save();renderModule()}
function renderModule(){let x=sub(S.current), ms=S.module[x.id]||{}, d=S.diag?.bySub?.[x.id];let traps={num_frac:'Watch units and preserve the order of ratios.',num_pct:'Distinguish “percent of” from “percent change.”',alg_linear:'Apply every operation to both sides of the equation.',alg_expr:'Exponent rules apply to matching bases—not to addition.',alg_quad:'After factoring, set each factor equal to zero.',func:'The value inside parentheses is the input, not multiplication.',lines:'Keep slope and y-intercept in their correct positions.',stats:'A mean is based on the total and the number of values.',prob:'The denominator must represent the full sample space.',geo_area:'Decide whether the question asks for length, area, or volume.',geo_coord:'Average coordinates for midpoint; use differences for distance.',geo_tri:'Identify the hypotenuse before using the Pythagorean theorem.',trig:'Opposite and adjacent depend on the reference angle.',poly:'Area scales by the square of a linear scale factor.',advanced:'Simplify structure before approximating decimals.'};shell(`<section class="card moduleHero"><div class="row"><span class="tag">${esc(x.domain)}</span><span class="spacer"></span><span class="pill">${S.mastered[x.id]?'✓ mastered':'assigned module'}</span></div><h1>${esc(x.name)}</h1><p class="sub">${esc(x.desc)}</p>${d?`<div class="evidence">Diagnostic evidence <b>${d.c}/${d.n}</b> • Mastery target <b>80%</b></div>`:''}</section>
<section class="lessonGrid"><section class="card"><div class="lessonNo">01</div><h2>Learn it</h2><h3>Worked example</h3><div class="qstem">${esc(x.example[0])}</div><div class="feedback">${esc(x.example[1])}</div><h3>Strategy to remember</h3><p class="sub">${esc(x.strategy[0])}</p></section><section class="card"><div class="lessonNo">02</div><h2>ACT lens</h2><div class="trap"><b>⚠ Common trap</b><p>${esc(traps[x.id])}</p></div><div class="tip"><b>⏱ Test-day habit</b><p>Before calculating, name what the question is asking for and estimate what a reasonable answer should look like.</p></div><div class="tip"><b>🧠 Mastery target</b><p>You should be able to recognize the method without a hint and execute it accurately.</p></div></section></section>
<section class="card"><div class="row"><div><div class="lessonNo">03</div><h2>Guided practice</h2><p class="sub">Three problems use a two-step routine: choose the strategy first, then solve. Strategy feedback teaches the method without disclosing the answer.</p></div><span class="spacer"></span><span class="pill">${ms.practiceDone?'✓ practice complete':'3 questions'}</span></div><button class="btn" onclick="startPractice('${x.id}')">${ms.practiceDone?'Practice again':'Start guided practice'} →</button></section>
<section class="card masteryGate"><div><div class="lessonNo">04</div><h2>Prove mastery</h2><p class="sub">Five fresh, unscaffolded questions: 2 easy, 2 medium, and 1 hard. Score 4/5 or better. Retakes use new values so completion reflects the skill—not memorization.</p>${ms.attempts?`<p class="tiny">Attempts: ${ms.attempts} • Best: ${ms.best||0}/5</p>`:''}</div><button class="btn" ${ms.practiceDone?'':'disabled'} onclick="startMini('${x.id}')">${S.mastered[x.id]?'Retake check':'Take mastery check'} →</button></section>`)}
function instructorView(){let stats=domainStats(), done=C.subtopics.filter(x=>S.mastered[x.id]).length;let rows=Object.entries(stats).map(([d,z])=>`<tr><td>${esc(d)}</td><td>${z.q?z.c+'/'+z.q:'—'}</td><td>${z.m}/${z.n}</td><td>${z.n?Math.round(z.m/z.n*100):0}%</td></tr>`).join('');shell(`<section class="card"><div class="eyebrow">INSTRUCTOR PREVIEW</div><h1>Instructional dashboard</h1><p class="sub">This static GitHub edition summarizes the student currently using this browser. A licensed production edition should connect the same data model to secure student accounts and a center-wide roster dashboard.</p></section><section class="grid"><div class="stat card"><div class="tiny">Student</div><div class="big">${esc(S.name||'Demo student')}</div></div><div class="stat card"><div class="tiny">Diagnostic</div><div class="big">${S.diag?S.diag.score+'/45':'—'}</div></div><div class="stat card"><div class="tiny">Mastered</div><div class="big">${done}/15</div></div><div class="stat card"><div class="tiny">Post</div><div class="big">${S.post?S.post.score+'/45':'—'}</div></div></section><section class="card"><h2>Domain evidence</h2><table><thead><tr><th>Domain</th><th>Diagnostic</th><th>Subtopics mastered</th><th>Completion</th></tr></thead><tbody>${rows}</tbody></table></section><section class="card"><h2>Learning-process analytics</h2>${(()=>{let a=strategyAnalytics();let attempts=Object.values(S.module||{}).reduce((n,m)=>n+(m.attempts||0),0);return `<div class="grid"><div class="stat"><div class="tiny">Strategy accuracy</div><div class="big">${a.n?a.pct+'%':'—'}</div><div class="tiny">${a.ok}/${a.n} guided decisions</div></div><div class="stat"><div class="tiny">Mastery attempts</div><div class="big">${attempts}</div></div><div class="stat"><div class="tiny">Modules compacted</div><div class="big">${C.subtopics.filter(x=>S.module[x.id]?.source==='diagnostic').length}</div></div><div class="stat"><div class="tiny">Modules learned</div><div class="big">${C.subtopics.filter(x=>S.module[x.id]?.source==='module').length}</div></div></div>`})()}</section><section class="card"><h2>Production center dashboard roadmap</h2><div class="grid"><div class="callout"><b>Roster + cohorts</b><span>Students grouped by tutor, class, site, and term.</span></div><div class="callout"><b>Assignment controls</b><span>Assign modules, deadlines, retakes, and targeted intervention.</span></div><div class="callout"><b>Analytics</b><span>Strategy errors vs. execution errors, time-on-task, attempts, and growth.</span></div><div class="callout"><b>License administration</b><span>Center seats, renewal dates, usage reporting, and branded reports.</span></div></div></section>`)}
// -------- Original question generators --------
function makeQBase(id,seed,kind='practice',variant=null,difficulty='standard'){let r=rng(seed), R=(a,b)=>Math.floor(r()*(b-a+1))+a, pick=a=>a[Math.floor(r()*a.length)], A=[], stem='', ans=0, exp='', visual='';
 const v=variant===null?Math.floor(r()*3):variant%3, hard=difficulty==='hard', med=difficulty==='medium';
 const mc=(correct,wrong)=>{let raw=[correct,...wrong].map(String), seen=new Set(raw);if(seen.size!==5){let base=Number(correct);if(Number.isFinite(base)){raw=[String(correct),...Array.from({length:4},(_,i)=>String(base+(i+1)*(base>=0?1:-1||1)))];}else throw new Error(`Duplicate answer choices generated for ${id} (seed ${seed}): ${raw.join(' | ')}`)}let vals=shuffle(raw,r);ans=vals.indexOf(String(correct));return vals};
 const strat=(text,correct,wrong)=>({strategyText:text,strategyChoices:shuffle([correct,...wrong],r),strategyCorrect:0}); let sm=null;
 const finishStrat=(text,correct,wrong)=>{let choices=shuffle([correct,...wrong],r);sm={strategyText:text,strategyChoices:choices,strategyCorrect:choices.indexOf(correct)}};
 switch(id){
 case'num_frac': if(v===0){let b=pick([3,4,5,6,8]),k=R(2,hard?8:5),u=R(2,7),t=b*k,c=u*k;stem=`A machine uses ${u} liters of coolant every ${b} hours. At the same rate, how many liters are used in ${t} hours?`;A=mc(c,[c+u,c-u,c+b,c+1]);exp=`Scale both parts of the rate by the same factor.`;finishStrat('Set up an equivalent rate and scale both quantities by the same factor.','Use an equivalent ratio or proportion',['Add the two quantities','Convert both numbers to percents','Use a perimeter formula']);}else if(v===1){let a=R(2,5),b=R(a+2,10),mult=R(2,hard?7:4),total=b*mult,c=a*mult;stem=`The ratio of blue tiles to all tiles in a design is ${a}:${b}. If the design has ${total} tiles, how many are blue?`;A=mc(c,[c+a,total-c,b*mult-a,c+1]);exp=`Treat ${a}/${b} as part/whole and scale to a total of ${total}.`;finishStrat('Interpret the ratio as part-to-whole, then scale it to the given total.','Write a part-to-whole proportion',['Subtract the ratio numbers','Use the Pythagorean theorem','Average the two ratio numbers']);}else{let d=pick([3,4,5,6]),n=R(1,d-1),whole=d*R(hard?8:4,hard?14:8),c=whole*n/d;stem=`A class has ${whole} students. If ${n}/${d} of them submitted an assignment early, how many students submitted early?`;A=mc(c,[whole-c,c+n,c+d,whole/d]);exp=`Multiply the whole by the fraction ${n}/${d}.`;finishStrat('Find a fraction of a whole by multiplying the whole by the fraction.','Multiply the whole by the fraction',['Add numerator and denominator','Cross-multiply two unrelated numbers','Find the perimeter']);}break;
 case'num_pct': if(v===0){let whole=R(4,12)*25,p=pick([10,20,25,30,40,60]),c=whole*p/100;stem=`What is ${p}% of ${whole}?`;A=mc(c,[c+10,c+5,Math.max(0,c-10),whole]);exp=`Convert the percent to a decimal and multiply by the whole.`;finishStrat('Translate “percent of” into decimal multiplication.','Convert the percent to a decimal and multiply',['Divide the percent by the whole','Add the percent to the whole','Use slope']);}else if(v===1){let orig=R(4,10)*20,p=pick([10,20,25,30]),c=orig*(100-p)/100;stem=`A jacket originally costs $${orig}. It is discounted ${p}%. What is the sale price?`;A=mc(c,[orig*p/100,orig-c,c+10,orig+p]);exp=`Find the amount remaining after the discount: ${100-p}% of the original price.`;finishStrat('A discount asks for the amount remaining, not just the amount removed.','Find the remaining percent of the original',['Add the discount percent','Find only the discount amount','Set up a triangle ratio']);}else{let old=R(4,10)*10,inc=pick([10,20,25,50]),neu=old*(100+inc)/100;stem=`A quantity increases from ${old} to ${neu}. What is the percent increase?`;A=mc(`${inc}%`,[`${inc+10}%`,`${Math.max(5,inc-10)}%`,`${Math.round(neu/old*100)}%`,`${inc+25}%`]);exp=`Percent change is change ÷ original × 100%.`;finishStrat('For percent change, compare the change to the original amount.','Use (change ÷ original) × 100%',['Divide by the new amount','Average the two values','Subtract and stop']);}break;
 case'alg_linear': if(v===0){let x=R(2,hard?16:12),a=R(2,7),b=R(1,12),c=a*x+b;stem=`If ${a}x + ${b} = ${c}, what is x?`;A=mc(x,[x+1,x-1,x+2,x+3]);exp=`Undo addition, then divide by the coefficient.`;finishStrat('Use inverse operations to isolate x.','Undo operations in reverse order',['Factor the expression','Use the distance formula','Average both sides']);}else if(v===1){let x=R(2,10),a=R(2,6),b=R(2,9),c=a*(x+b);stem=`Solve ${a}(x + ${b}) = ${c}.`;A=mc(x,[x+b,x+a,x-1,x+1]);exp=`Divide by ${a}, then subtract ${b}.`;finishStrat('Either distribute or undo the outside multiplication first; then isolate x.','Undo the outside multiplication first',['Square both sides','Find a common denominator','Use the quadratic formula']);}else{let small=R(5,hard?20:12),extra=R(2,8),total=3*small+extra;stem=`The larger of two numbers is ${extra} more than twice the smaller. Their sum is ${total}. What is the smaller number?`;A=mc(small,[small-1,small+1,2*small+extra,total-small]);exp=`Let x be the smaller number; then x+(2x+${extra})=${total}.`;finishStrat('Translate the verbal relationships into one equation in one variable.','Define a variable and write an equation',['Guess from the largest number','Multiply all numbers together','Use a circle formula']);}break;
 case'alg_expr': if(v===0){let a=R(2,6),b=R(2,5),m=R(2,5),n=R(2,5),c=a*b,p=m+n;stem=`Simplify ${a}x<sup>${m}</sup> · ${b}x<sup>${n}</sup>.`;A=mc(`${c}x^${p}`,[`${c+1}x^${p}`,`${c}x^${p+1}`,`${c}x^${Math.max(1,p-1)}`,`${a+b}x^${p}`]);exp=`Multiply coefficients and add exponents on the same base.`;finishStrat('Use the product rule for exponents on like bases.','Multiply coefficients and add exponents',['Add coefficients and multiply exponents','Subtract exponents','Distribute a percent']);}else if(v===1){let a=R(2,6),b=R(2,8),c=R(2,7);stem=`Which expression is equivalent to ${a}(${b}x - ${c})?`;let co=a*b,con=a*c;A=mc(`${co}x - ${con}`,[`${co}x - ${c}`,`${a+b}x - ${con}`,`${co}x + ${con}`,`${b}x - ${con}`]);exp=`Distribute ${a} to every term inside the parentheses.`;finishStrat('Apply the distributive property to every term.','Distribute the outside factor to each term',['Combine unlike terms first','Square each term','Divide the exponents']);}else{let m=R(6,hard?12:9),n=R(2,m-2),p=m-n;stem=`For x ≠ 0, simplify x<sup>${m}</sup>/x<sup>${n}</sup>.`;A=mc(`x^${p}`,[`x^${m+n}`,`x^${n-m}`,`x^${p+1}`,`${p}x`]);exp=`When dividing like bases, subtract exponents.`;finishStrat('Use the quotient rule for exponents.','Subtract the denominator exponent from the numerator exponent',['Add the exponents','Multiply the exponents','Cross-multiply']);}break;
 case'alg_quad': if(v===0){let u=R(2,7),w=R(2,8);while(w===u)w=R(2,8);let sum=u+w,prod=u*w;stem=`Which value is a solution of x² - ${sum}x + ${prod} = 0?`;A=mc(u,[u-1,u+1,w+1,w+2]);exp=`Factor using two numbers whose sum is ${sum} and product is ${prod}.`;finishStrat('Check whether the quadratic factors cleanly before using a longer method.','Factor the quadratic',['Use slope-intercept form','Take a mean','Use a proportion']);}else if(v===1){let a=R(2,7),b=R(2,8);stem=`Which is a factorization of x² + ${a-b}x - ${a*b}?`;A=mc(`(x + ${a})(x - ${b})`,[`(x - ${a})(x + ${b})`,`(x + ${a})(x + ${b})`,`(x - ${a})(x - ${b})`,`(x + ${a+b})(x - 1)`]);exp=`Find factors of -${a*b} whose sum is ${a-b}.`;finishStrat('Use the product-and-sum relationship to build the binomial factors.','Find two numbers with the required product and sum',['Complete a ratio table','Use SOHCAHTOA','Average the coefficients']);}else{let r1=R(1,6),r2=-R(2,7),sum=r1+r2,prod=r1*r2;stem=`A quadratic has zeros ${r1} and ${r2}. Which equation could represent it?`;let f=(s,p)=>`x² ${s<=0?'+ '+(-s):'- '+s}x ${p>=0?'+ '+p:'- '+(-p)} = 0`;let correct=f(sum,prod);A=mc(correct,[f(sum+1,prod),f(sum,-prod),f(sum+2,prod),f(sum,prod+1)]);exp=`Zeros ${r1} and ${r2} give factors (x-${r1})(x-${r2}), then expand.`;finishStrat('Turn each zero into a linear factor, then expand if needed.','Write factors from the zeros',['Add the zeros to both sides','Use the midpoint formula','Find percent change']);}break;
 case'func': if(v===0){let a=R(2,5),b=R(-6,6),x=R(2,7),c=a*x+b;stem=`If f(x) = ${a}x ${b>=0?'+ '+b:'- '+Math.abs(b)}, what is f(${x})?`;A=mc(c,[c+a,c-a,c+1,c-1]);exp=`Substitute ${x} for x.`;finishStrat('Function notation is an instruction to substitute the given input.','Substitute the input into the rule',['Solve f as a variable','Find the slope only','Cross-multiply']);}else if(v===1){let xs=[-2,0,3,5],ys=xs.map(z=>2*z+1),idx=R(0,3);stem=`Using the table, what is g(${xs[idx]})?`;A=mc(ys[idx],[ys[(idx+1)%4],ys[(idx+2)%4],xs[idx],ys[idx]+2]);visual=`<table class="math-table"><tr><th>x</th>${xs.map(z=>`<td>${z}</td>`).join('')}</tr><tr><th>g(x)</th>${ys.map(z=>`<td>${z}</td>`).join('')}</tr></table>`;exp=`Locate the input in the x-row and read its paired output.`;finishStrat('Read a function table by matching the input to its corresponding output.','Match the input with its output in the table',['Average the row','Subtract adjacent entries','Use the quadratic formula']);}else{let k=R(1,5);stem=`If h(x)=x²+${k}, which expression equals h(x+2)?`;A=mc(`x² + 4x + ${4+k}`,[`x² + 2x + ${2+k}`,`x² + ${4+k}`,`x² + 4x + ${k}`,`2x² + ${4+k}`]);exp=`Replace every x in h(x) with (x+2), then expand.`;finishStrat('For a transformed input, replace x everywhere with the entire new input.','Substitute (x + 2) for x, then simplify',['Add 2 only to the output','Multiply the function by 2','Use a proportion']);}break;
 case'lines': if(v===0){let m=pick([-4,-3,-2,2,3,4]),b=R(-6,6),fmt=(mm,bb)=>`y = ${mm}x ${bb>=0?'+ '+bb:'- '+Math.abs(bb)}`;stem=`Which equation has slope ${m} and y-intercept ${b}?`;A=mc(fmt(m,b),[fmt(-m,b),fmt(m,b+1),fmt(m,b-1),fmt(-m,b+2)]);exp=`In y=mx+b, m is slope and b is y-intercept.`;finishStrat('Match the slope and y-intercept to y = mx + b.','Use slope-intercept form',['Use the area formula','Factor the equation','Find a percent']);}else if(v===1){let x1=R(-5,0),y1=R(-2,8),dx=pick([2,3,4,5]),m=pick([-3,-2,2,3]),x2=x1+dx,y2=y1+m*dx;stem=`What is the slope of the line through (${x1}, ${y1}) and (${x2}, ${y2})?`;A=mc(m,[m+1,m-1,-m,dx]);exp=`Use (y₂-y₁)/(x₂-x₁).`;finishStrat('With two points, calculate rise over run.','Use the slope formula',['Average the coordinates','Use midpoint','Multiply the y-values']);}else{let x=R(1,6),m1=R(1,4),m2=m1+R(1,4),b1=R(2,9),b2=(m1-m2)*x+b1;stem=`The lines y=${m1}x+${b1} and y=${m2}x ${b2>=0?'+ '+b2:'- '+Math.abs(b2)} intersect. What is the x-coordinate of the intersection?`;A=mc(x,[x-1,x+1,x+2,m2-m1]);exp=`At the intersection the y-values are equal, so set the expressions equal.`;finishStrat('At an intersection, both equations have the same x and y values.','Set the two y-expressions equal',['Add the slopes','Use the distance formula','Multiply the equations']);}break;
 case'stats': if(v===0){let vals=[R(60,80),R(70,90),R(75,95),R(65,90)],mean=R(75,90),need=mean*5-vals.reduce((a,b)=>a+b,0);while(need<50||need>110){mean=R(75,90);need=mean*5-vals.reduce((a,b)=>a+b,0)}stem=`Four scores are ${vals.join(', ')}. What fifth score gives a mean of ${mean}?`;A=mc(need,[need+2,need-2,need+4,need-4]);exp=`Required total = mean × number of scores; subtract the known total.`;finishStrat('Work backward from the desired mean to the required total.','Find the required total, then subtract known values',['Choose the middle value','Find the range','Multiply only the largest score']);}else if(v===1){let vals=[R(5,12),R(13,18),R(19,25),R(26,32)];let c=Math.round(vals.reduce((a,b)=>a+b,0)/4);let total=vals.reduce((a,b)=>a+b,0);while(total%4){vals[3]++;total++}c=total/4;stem=`What is the mean of ${vals.join(', ')}?`;A=mc(c,[c-2,c-1,c+1,c+2]);exp=`Add all values and divide by 4.`;finishStrat('Mean is total divided by the number of values.','Add the values, then divide by the count',['Choose the middle number','Subtract smallest from largest','Count only values above 10']);}else{let vals=[R(2,5),R(6,9),R(10,13),R(14,17),R(18,22)].sort((a,b)=>a-b),c=vals[2];stem=`What is the median of ${vals.join(', ')}?`;A=mc(c,[vals[1],vals[3],vals[4]-vals[0],Math.round(vals.reduce((a,b)=>a+b,0)/5)]);exp=`With five ordered values, the median is the middle (third) value.`;finishStrat('For the median, order the data and locate the middle value.','Identify the middle value after ordering',['Add and divide','Find the range','Use a proportion']);}break;
 case'prob': if(v===0){let red=R(2,7),blue=R(2,7),green=R(1,5),tot=red+blue+green;stem=`A bag contains ${red} red, ${blue} blue, and ${green} green tokens. What is the probability of selecting a red token?`;A=mc(`${red}/${tot}`,[`${red+1}/${tot}`,`${red}/${tot+1}`,`${red+blue}/${tot}`,`${red}/${tot+2}`]);exp=`Probability = favorable outcomes ÷ total outcomes.`;finishStrat('Count favorable outcomes and divide by the total number of equally likely outcomes.','Use favorable ÷ total',['Add favorable and total','Use permutations','Find a mean']);}else if(v===1){let a=R(2,5),b=R(2,5),c=R(2,4),prod=a*b*c;stem=`A café offers ${a} breads, ${b} fillings, and ${c} sauces. How many meals can be made by choosing one of each?`;A=mc(prod,[a+b+c,a*b+b*c,prod+a,prod*2]);exp=`Use the multiplication principle: multiply the independent choices.`;finishStrat('For one choice from each independent category, multiply the number of options.','Use the multiplication principle',['Add all options','Use favorable ÷ total','Find a common denominator']);}else{let total=R(24,36),a=R(Math.ceil(total/2),total-5),b=R(Math.ceil(total/2),total-5),c=Math.max(1,a+b-total);stem=`In a group of ${total} students, ${a} study Spanish and ${b} study French. What is the minimum number who study both?`;A=mc(c,[0,c+1,Math.abs(a-b),Math.min(a,b)]);exp=`Minimum overlap is ${a}+${b}-${total}.`;finishStrat('Use inclusion-exclusion: if the two group totals exceed the population, the excess must overlap.','Add the groups and subtract the total population',['Multiply the group sizes','Divide the total by 2','Use a geometric formula']);}break;
 case'geo_area': if(v===0){let l=R(6,18),w=R(4,12),c=2*(l+w);stem=`A rectangular patio measures ${l} ft by ${w} ft. How many feet of edging are needed around it?`;A=mc(c,[l*w,l+w,2*l*w,c+2]);exp=`“Around” signals perimeter: 2l+2w.`;finishStrat('Identify whether the situation asks for boundary length or covered space.','Use perimeter because the question asks for “around”',['Use area','Use volume','Use slope']);}else if(v===1){let l=R(5,12),w=R(3,9),h=R(2,7),c=l*w*h;stem=`A rectangular prism measures ${l} cm by ${w} cm by ${h} cm. What is its volume?`;A=mc(c,[l*w,2*(l+w),l*w*2,c+h]);exp=`Volume of a rectangular prism is lwh.`;finishStrat('Volume measures three-dimensional space, so multiply all three dimensions.','Use V = lwh',['Use perimeter','Use triangle area','Average the dimensions']);}else{let rad=R(3,hard?12:8),c=`${rad*rad}π`;stem=`A circle has radius ${rad}. What is its area in terms of π?`;A=mc(c,[`${2*rad}π`,`${rad}π`,`${2*rad*rad}π`,`${rad*rad+rad}π`]);exp=`Circle area is πr².`;finishStrat('Area of a circle uses the square of the radius.','Use A = πr²',['Use C = 2πr','Double the radius only','Use the Pythagorean theorem']);}break;
 case'geo_coord': if(v===0){let x1=R(-6,2)*2,y1=R(-5,3)*2,x2=x1+R(2,6)*2,y2=y1+R(2,6)*2,cx=(x1+x2)/2,cy=(y1+y2)/2;stem=`What is the midpoint of (${x1}, ${y1}) and (${x2}, ${y2})?`;A=mc(`(${cx}, ${cy})`,[`(${cx+1}, ${cy})`,`(${cx-1}, ${cy})`,`(${cx}, ${cy+1})`,`(${cx}, ${cy-1})`]);exp=`Average x-coordinates and y-coordinates separately.`;finishStrat('A midpoint is the coordinate-wise average of the endpoints.','Average the x-values and the y-values',['Subtract coordinates','Use slope only','Multiply coordinates']);}else if(v===1){let x1=R(-3,3),y1=R(-3,3),dx=pick([3,6,8]),dy=dx===8?6:4,c=Math.sqrt(dx*dx+dy*dy);let x2=x1+dx,y2=y1+dy;stem=`What is the distance between (${x1}, ${y1}) and (${x2}, ${y2})?`;A=mc(c,[c+1,c-1,dx+dy,Math.abs(dx-dy)]);exp=`Use √((Δx)²+(Δy)²).`;finishStrat('Coordinate distance comes from the Pythagorean theorem.','Use the distance formula',['Average the coordinates','Use slope-intercept form','Add the coordinates']);}else{let h=R(-4,4),k=R(-4,4),rad=R(2,7),c=`(x ${h>=0?'- '+h:'+ '+(-h)})² + (y ${k>=0?'- '+k:'+ '+(-k)})² = ${rad*rad}`;stem=`A circle has center (${h}, ${k}) and radius ${rad}. Which equation represents it?`;A=mc(c,[`(x ${h>=0?'+ '+h:'- '+(-h)})² + (y ${k>=0?'+ '+k:'- '+(-k)})² = ${rad*rad}`,`(x ${h>=0?'- '+h:'+ '+(-h)})² + (y ${k>=0?'- '+k:'+ '+(-k)})² = ${rad}`,`x² + y² = ${rad*rad}`,`(x-${rad})²+(y-${rad})²=${rad*rad}`]);exp=`Circle form is (x-h)²+(y-k)²=r².`;finishStrat('Match the center and radius to standard circle form, watching the signs.','Use (x − h)² + (y − k)² = r²',['Use y = mx + b','Use midpoint','Find circumference']);}break;
 case'geo_tri': if(v===0){let triples=pick([[3,4,5],[5,12,13],[8,15,17],[7,24,25]]),k=R(1,hard?4:3),a=triples[0]*k,b=triples[1]*k,c=triples[2]*k;stem=`A right triangle has legs ${a} and ${b}. What is its hypotenuse?`;A=mc(c,[c-1,c+1,a+b,Math.abs(b-a)]);exp=`Use a²+b²=c².`;finishStrat('Two legs are known and the hypotenuse is unknown, so use the Pythagorean theorem.','Use a² + b² = c²',['Use similar-triangle scale factors','Add the angles only','Use circle area']);}else if(v===1){let small=pick([6,9,12]),scale=pick([1.5,2,2.5]),big=small*scale,side=pick([4,8,10]),c=side*scale;stem=`Two triangles are similar. A side of ${small} on the smaller triangle corresponds to ${big} on the larger. If another side of the smaller triangle is ${side}, what is its corresponding larger side?`;A=mc(c,[side+scale,side*2,c+scale,small+side]);exp=`Find the scale factor ${big}/${small}, then multiply the corresponding side.`;finishStrat('Similar figures preserve proportional side lengths.','Find and apply the scale factor',['Use the Pythagorean theorem regardless of shape','Add corresponding sides','Find the angle sum']);}else{let a=R(35,70),b=R(35,80);while(a+b>=160)b=R(35,70);let c=180-a-b;stem=`A triangle has angles ${a}° and ${b}°. What is the third angle?`;A=mc(`${c}°`,[`${c+5}°`,`${c-5}°`,`${c+10}°`,`${c-10}°`]);exp=`Triangle angles sum to 180°.`;finishStrat('Use the fixed angle sum of a triangle.','Subtract the known angles from 180°',['Use the Pythagorean theorem','Multiply the angles','Use a proportion']);}break;
 case'trig': if(v===0){let tri=pick([[3,4,5],[5,12,13],[8,15,17]]),opp=tri[0],adj=tri[1],hyp=tri[2];stem=`In a right triangle, relative to angle θ, the opposite side is ${opp} and the hypotenuse is ${hyp}. Which ratio gives sin θ?`;A=mc(`${opp}/${hyp}`,[`${adj}/${hyp}`,`${opp}/${adj}`,`${hyp}/${opp}`,`${hyp}/${adj}`]);exp=`Sine = opposite/hypotenuse.`;finishStrat('Label sides relative to the angle, then choose the matching trig ratio.','Use sine: opposite ÷ hypotenuse',['Use cosine: adjacent ÷ hypotenuse','Use tangent: opposite ÷ adjacent','Use the distance formula']);}else if(v===1){let tri=pick([[5,12,13],[7,24,25]]),adj=tri[0],hyp=tri[2],scale=R(2,4),H=hyp*scale,c=adj*scale;stem=`In a right triangle, cos A = ${adj}/${hyp} and the hypotenuse is ${H}. What is the adjacent side?`;A=mc(c,[adj*scale+1,tri[1]*scale,H-c,H]);exp=`Set adjacent/${H}=${adj}/${hyp} and scale.`;finishStrat('Use the given trig ratio as a proportion to scale the side lengths.','Set up cosine as adjacent ÷ hypotenuse',['Use sine instead','Add the numerator and denominator','Use polygon angle sum']);}else{let shadow=pick([10,12,15,18,20]),ang=pick([30,35,40,45,50]);stem=`A tree casts a ${shadow}-ft shadow. If the angle of elevation is ${ang}°, which expression gives the height h?`;A=mc(`${shadow} tan ${ang}°`,[`${shadow} sin ${ang}°`,`${shadow} cos ${ang}°`,`${shadow}/tan ${ang}°`,`tan ${ang}°/${shadow}`]);exp=`Tangent relates opposite height to adjacent shadow: tan θ=h/${shadow}.`;finishStrat('When opposite and adjacent are involved, tangent is the direct ratio.','Use tan θ = opposite ÷ adjacent',['Use sine','Use cosine','Use circle area']);}break;
 case'poly': if(v===0){let n=pick([5,6,8,9,10,12]),c=(n-2)*180/n;stem=`A regular ${n}-gon has equal interior angles. What is one interior angle?`;A=mc(`${c}°`,[`${360/n}°`,`${c-10}°`,`${c+10}°`,`${c+20}°`]);exp=`Interior sum is (n−2)180°, then divide by n.`;finishStrat('For one angle of a regular polygon, find the interior sum and divide equally.','Use (n − 2)180° ÷ n',['Use 360° ÷ n for an interior angle','Use area','Use slope']);}else if(v===1){let n=pick([5,6,7,8,9,10]),c=n*(n-3)/2;stem=`How many diagonals does a ${n}-gon have?`;A=mc(c,[n,n-3,n*(n-3),c+1]);exp=`Diagonals = n(n−3)/2.`;finishStrat('Count diagonals without double-counting each connection.','Use n(n − 3)/2',['Use (n − 2)180','Use 2πr','Multiply n by 2']);}else{let a=pick([2,3,4]),b=a+R(2,4),c=`${a*a}:${b*b}`;stem=`Two circles have radii in the ratio ${a}:${b}. What is the ratio of their areas?`;A=mc(c,[`${a}:${b}`,`${2*a}:${2*b}`,`${a*a*a}:${b*b*b}`,`${b*b}:${a*a}`]);exp=`Area scales with the square of the radius.`;finishStrat('For similar circles, area changes by the square of the radius scale factor.','Square both parts of the radius ratio',['Keep the same ratio','Cube the ratio','Add the radii']);}break;
 case'advanced': if(v===0){let roots=pick([[12,2,3],[20,2,5],[27,3,3],[45,3,5],[75,5,3],[98,7,2]]),N=roots[0],co=roots[1],inside=roots[2];stem=`Simplify √${N}.`;A=mc(`${co}√${inside}`,[`${co-1}√${inside}`,`${co+1}√${inside}`,`${co}√${inside+1}`,`${co*inside}`]);exp=`Factor out the largest perfect-square factor.`;finishStrat('Look for a perfect-square factor inside the radical.','Factor out a perfect square',['Square the entire expression','Add factors','Use slope']);}else if(v===1){let a=R(2,6),b=R(1,6),c=R(2,7),d=-R(1,7),real=a+c,imag=b+d;stem=`If i²=-1, what is (${a}+${b}i)+(${c}${d>=0?'+':'-'}${Math.abs(d)}i)?`;let fmt=(re,im)=>`${re}${im>=0?'+':'-'}${Math.abs(im)}i`;A=mc(fmt(real,imag),[fmt(real,b-d),fmt(a-c,imag),fmt(real+1,imag),fmt(a*c,b*d)]);exp=`Combine real parts and imaginary parts separately.`;finishStrat('Treat real and imaginary parts as separate like terms.','Combine real parts and imaginary parts separately',['Multiply all four numbers','Replace i with 1','Use the quadratic formula']);}else{let base=pick([2,3,5]),power=R(3,hard?6:5),shift=R(1,3),rhs=base**power,c=power-shift;stem=`Solve ${base}^(x+${shift}) = ${rhs}.`;A=mc(c,[c-1,c+1,power,power+shift]);exp=`Rewrite ${rhs} as ${base}^${power}; then x+${shift}=${power}.`;finishStrat('When both sides can use the same base, equate the exponents.','Rewrite with a common base, then equate exponents',['Take a mean','Factor a triangle','Use percent change']);}break;
 }
 return {id:`${id}-${seed}-${v}-${difficulty}`,sub:id,stem,choices:A,answer:ans,explain:exp,visual,...(sm||{}),difficulty,variant:v};}

function makeQExtra(id,seed,variant,difficulty='standard'){
 let r=rng(seed),R=(a,b)=>Math.floor(r()*(b-a+1))+a,pick=a=>a[Math.floor(r()*a.length)],ans=0,stem='',exp='',visual='',sm={};
 const mc=(correct,wrong)=>{let raw=[correct,...wrong].map(String), uniq=[];for(const x of raw)if(!uniq.includes(x))uniq.push(x);let n=Number(correct),step=1;while(uniq.length<5&&Number.isFinite(n)){let cand=String(n+(step++));if(!uniq.includes(cand))uniq.push(cand)}for(const cand of ['Cannot be determined','0','1','-1','None of these']){if(uniq.length>=5)break;if(!uniq.includes(cand))uniq.push(cand)}let vals=shuffle(uniq.slice(0,5),r);ans=vals.indexOf(String(correct));return vals};
 const strategy=(text,correct,wrong)=>{let choices=shuffle([correct,...wrong],r);sm={strategyText:text,strategyChoices:choices,strategyCorrect:choices.indexOf(correct)}};
 let A=[];
 switch(id){
  case'num_frac': if(variant===3){let cups=pick([3,4,5]),serv=pick([6,8,10]),target=serv*2,c=cups*2;stem=`A recipe uses ${cups} cups of flour for ${serv} servings. How many cups are needed for ${target} servings?`;A=mc(c,[cups+2,cups*serv,target/cups,c+1]);exp=`The number of servings doubled, so the amount of flour must double.`;strategy('Look for a scale factor between the original and new quantities.','Use the scale factor on both quantities',['Add the change in servings to the flour','Convert the numbers to percents','Use a unit-area formula']);}else{let total=pick([24,30,36,40]),part=pick([6,8,10,12]);while(total%part!==0)part=pick([6,8,10,12]);let g=(a,b)=>b?g(b,a%b):a,d=g(part,total),c=`${part/d}/${total/d}`;stem=`${part} of ${total} students chose option A. What fraction of the students chose option A, in simplest form?`;A=mc(c,[`${part}/${total-part}`,`${total/part}/1`,`1/${total/part+1}`,`${total-part}/${total}`]);exp=`Write part over whole, then reduce by the greatest common factor.`;strategy('A fraction of a group is part ÷ whole, then simplify.','Write part over whole and reduce',['Use a proportion with an unknown','Subtract part from whole and stop','Multiply part and whole']);}break;
  case'num_pct': if(variant===3){let p=pick([20,25,40,50]),part=pick([30,40,60,80]),whole=part*100/p;stem=`${part} is ${p}% of what number?`;A=mc(whole,[part*p/100,part+ p,whole-part,whole+p]);exp=`Use part = percent × whole, so whole = part ÷ decimal percent.`;strategy('When the whole is unknown, divide the part by the decimal percent.','Use whole = part ÷ percent',['Multiply the part by the percent','Add the percent to the part','Use percent change']);}else{let p=pick([10,15,20,25]),orig=pick([80,100,120,160]),c=orig*(1+p/100);stem=`A membership fee of $${orig} increases by ${p}%. What is the new fee?`;A=mc(c,[orig*p/100,orig-p,orig+p,c+p]);exp=`An increase leaves 100% + ${p}% = ${100+p}% of the original.`;strategy('For a percent increase, multiply the original by 1 plus the decimal rate.','Use original × (1 + rate)',['Find only the amount of increase','Subtract the rate from 1','Divide the new value by the rate']);}break;
  case'alg_linear': if(variant===3){let x=R(3,10),a=R(2,5),b=R(2,7),c=R(1,6),rhs=a*x+b-c*x;stem=`Solve ${a}x + ${b} = ${c}x + ${rhs}.`;A=mc(x,[x-1,x+1,x+2,Math.abs(rhs-b)]);exp=`Move variable terms to one side and constants to the other before dividing.`;strategy('Variables appear on both sides, so collect variable terms first.','Move x-terms to one side and constants to the other',['Distribute a percent','Factor as a quadratic','Use slope']);}else{let rate=R(3,8),fee=R(4,12),total=fee+rate*R(4,10),c=(total-fee)/rate;stem=`A bike rental costs $${fee} plus $${rate} per hour. If the total is $${total}, how many hours was the bike rented?`;A=mc(c,[c+1,c-1,total/rate,fee+rate]);exp=`Model the situation as ${fee}+${rate}h=${total}, then isolate h.`;strategy('Translate the fixed fee plus hourly rate into a linear equation.','Write fixed fee + rate·time = total',['Divide total by the hourly rate immediately','Use a system of two equations','Find percent change']);}break;
  case'alg_expr': if(variant===3){let a=R(2,5),b=R(2,6),c=R(2,5),coef=a+c,con=a*b;stem=`Simplify ${a}(x + ${b}) + ${c}x.`;A=mc(`${coef}x + ${con}`,[`${a+c+b}x`,` ${coef}x + ${b}`.trim(),`${a*c}x + ${con}`,`${coef+1}x + ${con}`]);exp=`Distribute first, then combine the like x-terms.`;strategy('This expression needs two moves: distribute, then combine like terms.','Distribute, then combine like terms',['Combine terms inside parentheses first','Multiply the x-coefficients','Use the quotient rule']);}else{let a=R(2,5),m=R(2,4),p=R(2,4),c=a**p,e=m*p;stem=`Simplify (${a}x^${m})^${p}.`;A=mc(`${c}x^${e}`,[`${a*p}x^${m+p}`,`${c}x^${m+p}`,`${a}x^${e}`,`${c+p}x^${e}`]);exp=`Raise the coefficient to the power and multiply exponents: (x^m)^p=x^(mp).`;strategy('A power applied to a product affects the coefficient and the variable factor.','Raise each factor to the power and multiply exponents',['Add all exponents','Multiply the coefficient by the power only','Distribute across addition']);}break;
  case'alg_quad': if(variant===3){let h=R(1,6),k=R(2,8);stem=`The graph of y=(x-${h})²-${k} has its vertex at which point?`;A=mc(`(${h}, -${k})`,[`(-${h}, -${k})`,`(${h}, ${k})`,`(-${h}, ${k})`,`(${k}, -${h})`]);exp=`Vertex form y=(x-h)²+k has vertex (h,k).`;strategy('Recognize vertex form instead of expanding the quadratic.','Read (h, k) directly from vertex form',['Factor to find two roots','Use the quadratic formula','Find the slope']);}else{let r=R(2,7),c=r*r;stem=`Solve x² = ${c}.`;A=mc(`x = ±${r}`,[`x = ${r}`,`x = -${r}`,`x = ±${c}`,`x = ${c/2}`]);exp=`Taking the square root of both sides gives both the positive and negative roots.`;strategy('When x² equals a positive constant, use the square-root property and include both signs.','Take square roots and use ±',['Factor out x','Use a proportion','Complete a table']);}break;
  case'func': if(variant===3){let a=R(2,5),b=R(1,6),out=R(12,30),x=(out-b)/a;if(!Number.isInteger(x)){out=a*R(3,7)+b;x=(out-b)/a}stem=`If f(x)=${a}x+${b} and f(x)=${out}, what is x?`;A=mc(x,[x-1,x+1,out/a,out-b]);exp=`Set the function rule equal to the given output and solve for the input.`;strategy('This time the output is known and the input is unknown.','Set f(x) equal to the output and solve for x',['Substitute the output for x','Read a table','Find the y-intercept only']);}else{let shift=R(2,5);stem=`If g(x)=f(x-${shift}), how is the graph of f shifted to obtain g?`;A=mc(`${shift} units right`,[`${shift} units left`,`${shift} units up`,`${shift} units down`,`reflected across the x-axis`]);exp=`Replacing x with x-${shift} shifts the graph right ${shift} units.`;strategy('Horizontal shifts work opposite the sign inside the function input.','Interpret the change inside the input as a horizontal shift',['Add the shift to every output','Find a function value','Set the function equal to zero']);}break;
  case'lines': if(variant===3){let m=pick([-3,-2,2,3]),x=R(1,5),y=R(2,10),b=y-m*x;stem=`A line has slope ${m} and passes through (${x}, ${y}). What is its y-intercept?`;A=mc(b,[b+1,b-1,y-m,x-y]);exp=`Substitute the point and slope into y=mx+b and solve for b.`;strategy('A slope and one point determine the intercept through y = mx + b.','Substitute the point into y = mx + b and solve for b',['Use the distance formula','Average the coordinates','Set x equal to zero immediately']);}else{let m=pick([-4,-3,-2,2,3,4]);stem=`A line is perpendicular to a line with slope ${m}. What is the perpendicular slope?`;let c=String(-1/m);A=mc(c,[String(1/m),String(-m),String(m),String(m===0?0:1)]);exp=`Perpendicular nonvertical lines have slopes that are negative reciprocals.`;strategy('Perpendicular slope requires both a reciprocal and a sign change.','Take the negative reciprocal',['Use the same slope','Change only the sign','Take only the reciprocal']);}break;
  case'stats': if(variant===3){let vals=[R(4,8),R(9,12),R(13,16),R(17,20),R(21,24)].sort((a,b)=>a-b),c=vals[2];stem=`What is the median of the data set ${vals.join(', ')}?`;A=mc(c,[vals[1],vals[3],Math.round(vals.reduce((a,b)=>a+b,0)/5),vals[4]-vals[0]]);exp=`With five ordered values, the median is the middle (third) value.`;strategy('Median is about position after ordering, not the total.','Order the data and select the middle value',['Add and divide by the count','Subtract the minimum from maximum','Choose the most frequent value']);}else{let a=R(70,85),b=R(80,95),wa=40,wb=60,c=(a*wa+b*wb)/100;stem=`A course grade is 40% quizzes and 60% tests. If the quiz average is ${a} and the test average is ${b}, what is the weighted course average?`;A=mc(c,[Math.round((a+b)/2),a*.6+b*.4,c+2,c-2]);exp=`Multiply each category by its weight, then add the weighted contributions.`;strategy('Different categories contribute different percentages, so use a weighted mean.','Multiply each value by its weight, then add',['Take an ordinary mean','Use the median','Multiply the two scores']);}break;
  case'prob': if(variant===3){let red=R(2,5),blue=R(2,5),tot=red+blue,c=`${red}/${tot} × ${blue}/${tot-1}`;stem=`A bag has ${red} red and ${blue} blue tiles. Two tiles are drawn without replacement. Which expression gives P(red, then blue)?`;A=mc(c,[`${red}/${tot} + ${blue}/${tot}`,`${red}/${tot} × ${blue}/${tot}`,`${blue}/${tot} × ${red}/${tot}`,`${red+blue}/${tot}`]);exp=`Multiply sequential probabilities and reduce the denominator after the first draw.`;strategy('Without replacement changes the total before the second draw.','Multiply sequential probabilities and update the second denominator',['Add the two probabilities','Use the same denominator twice','Use inclusion-exclusion']);}else{let p=pick([0.2,0.25,0.3,0.4]),c=(1-p).toFixed(2);stem=`If the probability of rain is ${p}, what is the probability that it does not rain?`;A=mc(c,[p.toFixed(2),(1+p).toFixed(2),(p/2).toFixed(2),(1-p/2).toFixed(2)]);exp=`An event and its complement have probabilities that sum to 1.`;strategy('“Does not” signals the complement of the stated event.','Use 1 − P(event)',['Multiply by 2','Use favorable ÷ total from scratch','Add the probabilities']);}break;
  case'geo_area': if(variant===3){let b=R(6,14),h=R(4,12),c=b*h/2;stem=`A triangle has base ${b} and height ${h}. What is its area?`;A=mc(c,[b*h,b+h,2*(b+h),c+h]);exp=`Triangle area is one-half base times height.`;strategy('A triangle uses half the area of a rectangle with the same base and height.','Use A = ½bh',['Use A = bh','Use perimeter','Use the Pythagorean theorem']);}else{let s=R(3,8),c=6*s*s;stem=`A cube has side length ${s}. What is its total surface area?`;A=mc(c,[s**3,4*s*s,6*s,12*s]);exp=`A cube has six congruent square faces, each with area s².`;strategy('Surface area counts the areas of all exposed faces.','Find one face area and multiply by 6',['Use volume s³','Add the edge lengths','Use circle area']);}break;
  case'geo_coord': if(variant===3){let x=R(2,7),y=R(2,7);stem=`In which quadrant is the point (-${x}, ${y})?`;A=mc('Quadrant II',['Quadrant I','Quadrant III','Quadrant IV','On an axis']);exp=`Negative x and positive y place a point in Quadrant II.`;strategy('Use the signs of x and y to identify the quadrant.','Match the coordinate signs to a quadrant',['Use the distance formula','Average the coordinates','Find slope']);}else{let m=pick([-3,-2,2,3]),x=R(1,4),y=R(-2,5),c=y-m*x;stem=`Which equation represents the line with slope ${m} through (${x}, ${y})?`;let fmt=b=>`y = ${m}x ${b>=0?'+ '+b:'- '+Math.abs(b)}`;A=mc(fmt(c),[fmt(c+1),fmt(c-1),`y = ${-m}x + ${c}`,`x = ${x}`]);exp=`Use y=mx+b with the given point to determine b.`;strategy('Coordinate geometry can combine a point with slope-intercept form.','Substitute the point into y = mx + b',['Use midpoint','Use circle form','Use distance']);}break;
  case'geo_tri': if(variant===3){let a=R(30,70),c=R(30,70);while(a+c>=150)c=R(30,60);let ext=a+c;stem=`A triangle has two remote interior angles of ${a}° and ${c}°. What is the exterior angle at the third vertex?`;A=mc(`${ext}°`,[`${180-ext}°`,`${Math.abs(a-c)}°`,`${ext+10}°`,`${180-a}°`]);exp=`An exterior angle equals the sum of the two remote interior angles.`;strategy('Use the exterior-angle theorem instead of finding every interior angle first.','Add the two remote interior angles',['Subtract the angles','Use Pythagorean theorem','Set up a similarity ratio']);}else{let scale=pick([2,3]),small=R(3,7),per=small*3,c=per*scale;stem=`Two similar triangles have scale factor ${scale} from smaller to larger. If the smaller triangle has perimeter ${per}, what is the larger perimeter?`;A=mc(c,[per+scale,per*scale*scale,per/scale,c+small]);exp=`All linear measurements, including perimeter, scale by the same factor.`;strategy('Perimeter is a linear measurement, so it uses the side-length scale factor.','Multiply the perimeter by the scale factor',['Square the scale factor','Use the angle sum','Use the Pythagorean theorem']);}break;
  case'trig': if(variant===3){let tri=pick([[3,4,5],[5,12,13],[8,15,17]]),opp=tri[0],adj=tri[1];stem=`In a right triangle, relative to θ, opposite=${opp} and adjacent=${adj}. Which ratio equals tan θ?`;A=mc(`${opp}/${adj}`,[`${adj}/${opp}`,`${opp}/${tri[2]}`,`${adj}/${tri[2]}`,`${tri[2]}/${opp}`]);exp=`Tangent is opposite over adjacent.`;strategy('The named sides are opposite and adjacent, which points directly to tangent.','Use tangent: opposite ÷ adjacent',['Use sine','Use cosine','Use Pythagorean theorem first']);}else{let tri=pick([[3,4,5],[5,12,13]]),adj=tri[1],hyp=tri[2];stem=`In a right triangle, relative to θ, adjacent=${adj} and hypotenuse=${hyp}. Which ratio equals cos θ?`;A=mc(`${adj}/${hyp}`,[`${tri[0]}/${hyp}`,`${tri[0]}/${adj}`,`${hyp}/${adj}`,`${adj}/${tri[0]}`]);exp=`Cosine is adjacent over hypotenuse.`;strategy('The named sides are adjacent and hypotenuse, which points directly to cosine.','Use cosine: adjacent ÷ hypotenuse',['Use sine','Use tangent','Use the distance formula']);}break;
  case'poly': if(variant===3){let r=R(3,9),c=`${2*r}π`;stem=`A circle has radius ${r}. What is its circumference?`;A=mc(c,[`${r*r}π`,`${r}π`,`${4*r}π`,`${2*r*r}π`]);exp=`Circumference is 2πr.`;strategy('Circumference measures distance around a circle.','Use C = 2πr',['Use A = πr²','Use polygon angle sum','Square the radius ratio']);}else{let arc=pick([60,90,120,150]),r=pick([3,6,9]),c=`${arc/360*2*r}π`;stem=`A circle has radius ${r}. What is the arc length of a ${arc}° arc?`;A=mc(c,[`${arc/360*r*r}π`,`${2*r}π`,`${arc/180*r*r}π`,`${arc}π`]);exp=`Arc length is the same fraction of circumference as the central angle is of 360°.`;strategy('Arc length is a fraction of the full circumference.','Use (central angle ÷ 360) × circumference',['Use circle area','Use the polygon diagonal formula','Use radius ratio only']);}break;
  case'advanced': if(variant===3){let a=R(2,6),b=R(2,6),c=a*a-b*b;stem=`Simplify (${a}+${b}i)(${a}-${b}i).`;A=mc(a*a+b*b,[c,`${a*a}-${b*b}i`,a+b,a*b]);exp=`Conjugates multiply to a²+b² because i²=-1.`;strategy('Recognize complex conjugates and use the difference-of-squares structure.','Multiply conjugates; replace i² with −1',['Add real and imaginary parts','Use exponent rules only','Take a square root']);}else{let a=R(2,6),b=R(1,5),c=R(8,25),x=(c-b)/a;if(!Number.isInteger(x)){c=a*R(2,6)+b;x=(c-b)/a}stem=`Solve |${a}x + ${b}| = ${c}. Which is one possible value of x?`;let x2=(-c-b)/a;A=mc(x,[x+1,x-1,x2+1,c-b]);exp=`An absolute-value equation creates two cases: ${a}x+${b}=${c} or ${a}x+${b}=-${c}.`;strategy('Absolute value equations split into a positive case and a negative case.','Write and solve two linear equations',['Drop the absolute-value bars','Square only one side','Use a circle formula']);}break;
 }
 return {id:`${id}-${seed}-${variant}-${difficulty}`,sub:id,stem,choices:A,answer:ans,explain:exp,visual,...sm,difficulty,variant};
}
function makeQ(id,seed,kind='practice',variant=null,difficulty='standard'){
 const v=variant===null?Math.floor(rng(seed)()*5):((variant%5)+5)%5;
 return v<3?makeQBase(id,seed,kind,v,difficulty):makeQExtra(id,seed,v,difficulty);
}
function startPractice(id){S.run={type:'practice',sub:id,i:0,qs:[0,2,4].map((v,k)=>makeQ(id,S.seed++ + k*101,'practice',v,'guided')),answers:[],strategy:[]};save();renderPractice()}
function renderPractice(){let R=S.run,q=R.qs[R.i],x=sub(R.sub), st=x.strategy, state=R.strategy[R.i];let strategyChoices=q.strategyChoices||st[1], strategyCorrect=q.strategyCorrect??x.strategyCorrect, strategyText=q.strategyText||st[0];shell(`<section class="card"><div class="row"><span class="tag">Guided practice ${R.i+1}/3</span><span class="spacer"></span><span>${esc(x.name)}</span></div><div class="progress"><i style="width:${R.i/3*100}%"></i></div></section><section class="card"><h2>Step 1 • Choose a strategy</h2><div class="qstem">${q.stem}</div>${q.visual||''}<p class="sub">Which approach should you use? You are choosing a method—not solving yet.</p>${strategyChoices.map((c,i)=>`<button class="choice ${state!==undefined?(i===strategyCorrect?'correct':i===state&&state!==strategyCorrect?'wrong':''):''}" ${state!==undefined?'disabled':''} onclick="pickStrategy(${i})">${esc(c)}</button>`).join('')}${state!==undefined?`<div class="feedback ${state===strategyCorrect?'good':'bad'}"><b>${state===strategyCorrect?'✓ Good strategy':'Not quite — use this strategy:'}</b> ${esc(strategyText)}<br><span class="tiny">Notice that this explains the approach without giving away the answer.</span></div><button class="btn" onclick="renderSolve()">Now solve it →</button>`:''}</section>`)}
function pickStrategy(i){let x=sub(S.run.sub),q=S.run.qs[S.run.i],correct=q.strategyCorrect??x.strategyCorrect;S.run.strategy[S.run.i]=i;S.activity=S.activity||[];S.activity.push({t:Date.now(),type:'strategy',sub:S.run.sub,correct:i===correct});save();renderPractice()}
function renderSolve(){let R=S.run,q=R.qs[R.i],chosen=R.answers[R.i];shell(`<section class="card"><span class="tag">Step 2 • Solve</span><div class="qstem">${q.stem}</div>${q.visual||''}${q.choices.map((c,i)=>`<button class="choice ${chosen!==undefined?(i===q.answer?'correct':i===chosen&&chosen!==q.answer?'wrong':''):''}" ${chosen!==undefined?'disabled':''} onclick="pickPracticeAnswer(${i})">${String.fromCharCode(65+i)}. ${c}</button>`).join('')}${chosen!==undefined?`<div class="feedback ${chosen===q.answer?'good':'bad'}"><b>${chosen===q.answer?'✓ Correct!':'Correct answer: '+String.fromCharCode(65+q.answer)}</b><br>${q.explain}</div><button class="btn" onclick="nextPractice()">${R.i===2?'Finish practice':'Next question'} →</button>`:''}</section>`)}
function pickPracticeAnswer(i){let q=S.run.qs[S.run.i];S.run.answers[S.run.i]=i;S.activity=S.activity||[];S.activity.push({t:Date.now(),type:'practice',sub:S.run.sub,correct:i===q.answer});save();renderSolve()}
function nextPractice(){if(S.run.i<2){S.run.i++;save();renderPractice()}else{let id=S.run.sub;S.module[id]=S.module[id]||{};S.module[id].practiceDone=true;save();S.current=id;renderModule()}}
function startMini(id){let attempt=(S.module[id]?.attempts||0)+1,diffs=['easy','easy','medium','medium','hard'];S.run={type:'mini',sub:id,i:0,qs:diffs.map((d,k)=>makeQ(id,S.seed++ + k*173+attempt*997,'mastery',k,d)),answers:[],difficulties:diffs};save();renderMini()}
function renderMini(){let R=S.run,q=R.qs[R.i],chosen=R.answers[R.i];shell(`<section class="card"><div class="row"><span class="tag">Mastery check</span><span class="spacer"></span><span class="pill">${(R.difficulties?.[R.i]||'').toUpperCase()}</span><b>${R.i+1}/5</b></div><div class="progress"><i style="width:${R.i/5*100}%"></i></div><div class="qstem">${q.stem}</div>${q.visual||''}${q.choices.map((c,i)=>`<button class="choice" ${chosen!==undefined?'disabled':''} onclick="pickMini(${i})">${String.fromCharCode(65+i)}. ${c}</button>`).join('')}${chosen!==undefined?`<button class="btn" onclick="nextMini()">${R.i===4?'Submit mastery check':'Next'} →</button>`:''}</section>`)}
function pickMini(i){let q=S.run.qs[S.run.i];S.run.answers[S.run.i]=i;S.activity=S.activity||[];S.activity.push({t:Date.now(),type:'mastery_item',sub:S.run.sub,correct:i===q.answer});save();renderMini()}
function nextMini(){let R=S.run;if(R.i<4){R.i++;save();renderMini();return}let score=R.answers.reduce((n,a,i)=>n+(a===R.qs[i].answer),0),id=R.sub;S.module[id]=S.module[id]||{};S.module[id].attempts=(S.module[id].attempts||0)+1;S.module[id].last=score;S.module[id].best=Math.max(S.module[id].best||0,score);if(score>=4){S.mastered[id]=true;S.module[id].source='module'}save();shell(`<section class="card hero"><div class="eyebrow">MASTERY CHECK</div><h1>${score>=4?'Module mastered!':'Almost there.'}</h1><p class="sub">You scored <b>${score}/5</b>. ${score>=4?'That meets the 80% mastery target. This subtopic is now complete.':'You need 4/5 to complete the module. Review the example and try a fresh version.'}</p><div class="row"><button class="btn" onclick="go('modules')">Back to modules</button>${score>=4&&C.subtopics.filter(x=>S.mastered[x.id]).length%3===0?'<button class="btn secondary" onclick="brainBreak()">Take a brain break</button>':''}<button class="btn secondary" onclick="openModule('${id}')">${score>=4?'Review':'Try again'}</button></div></section>`)}

function makePost(){let qs=[];C.subtopics.forEach((x,si)=>{for(let k=0;k<3;k++)qs.push(makeQ(x.id,70000+si*1009+k*131,'post'))});return shuffle(qs,rng(424242))}
function startTest(type,retake=false){if(type==='post'&&C.subtopics.some(x=>!S.mastered[x.id]))return;let qs=type==='diag'?shuffle(C.diagnostic,rng(31337)):makePost();S.run={type,i:0,qs,answers:Array(qs.length),started:Date.now(),remaining:3000};save();renderTest()}
let timerHandle=null;
function renderTest(){clearInterval(timerHandle);let R=S.run,q=R.qs[R.i],chosen=R.answers[R.i];R.flagged=R.flagged||[];let answered=R.answers.filter(x=>x!==undefined).length;let nav=R.qs.map((_,i)=>`<button class="qnav ${R.answers[i]!==undefined?'answered':''} ${R.flagged.includes(i)?'flagged':''} ${i===R.i?'current':''}" onclick="jumpTest(${i})">${i+1}</button>`).join('');shell(`<section class="card"><div class="row"><span class="tag">${R.type==='diag'?'Diagnostic':'Post-assessment'}</span><span class="spacer"></span><b>Question ${R.i+1} of 45</b><span class="pill" id="timer">50:00</span></div><div class="progress"><i style="width:${answered/45*100}%"></i></div><p class="tiny">${answered}/45 answered • ${R.flagged.length} flagged for review • progress autosaves in this browser</p></section><section class="testLayout"><section class="card"><div class="qstem">${q.stem}</div>${q.visual||''}${q.choices.map((c,i)=>`<button class="choice ${chosen===i?'selected':''}" onclick="pickTest(${i})">${String.fromCharCode(65+i)}. ${c}</button>`).join('')}<div class="row"><button class="btn secondary" onclick="toggleFlag()">${R.flagged.includes(R.i)?'★ Flagged':'☆ Flag for review'}</button><span class="spacer"></span><button class="btn secondary" ${R.i===0?'disabled':''} onclick="testNav(-1)">← Back</button><button class="btn" onclick="testNav(1)">${R.i===44?'Review & submit':'Next →'}</button></div></section><aside class="card testNav"><h3>Question navigator</h3><div class="qgrid">${nav}</div><div class="legend"><span>● answered</span><span>★ flagged</span></div>${R.i===44?`<button class="btn" onclick="reviewTest()">Review test</button>`:''}</aside></section><section class="card tiny">Diagnostic and post-assessment questions intentionally do not provide immediate correctness feedback so the scores remain useful as assessment data.</section>`);tick();timerHandle=setInterval(tick,1000)}
function jumpTest(i){S.run.i=i;save();renderTest()}
function toggleFlag(){let R=S.run;R.flagged=R.flagged||[];let i=R.flagged.indexOf(R.i);if(i>=0)R.flagged.splice(i,1);else R.flagged.push(R.i);save();renderTest()}
function reviewTest(){let R=S.run,un=R.answers.map((a,i)=>a===undefined?i:null).filter(x=>x!==null);shell(`<section class="card"><div class="eyebrow">FINAL REVIEW</div><h1>Check your work before submitting</h1><p class="sub">You have answered <b>${45-un.length}/45</b> questions. ${un.length?`There are <b>${un.length}</b> unanswered questions.`:'Every question has an answer.'}</p>${un.length?`<div class="notice">Unanswered: ${un.map(i=>`<button class="btn secondary" onclick="jumpTest(${i})">${i+1}</button>`).join(' ')}</div>`:''}<p>Flagged for review: ${R.flagged?.length?R.flagged.map(i=>`<button class="btn secondary" onclick="jumpTest(${i})">${i+1}</button>`).join(' '):'None'}</p><div class="row"><button class="btn secondary" onclick="renderTest()">Return to test</button><button class="btn" onclick="confirmSubmit()">Submit assessment</button></div></section>`)}
function confirmSubmit(){let un=S.run.answers.filter(x=>x===undefined).length;if(un&&!confirm(`You still have ${un} unanswered question${un===1?'':'s'}. Submit anyway?`))return;finishTest()}
function tick(){let R=S.run;if(!R||!['diag','post'].includes(R.type))return;let sec=Math.max(0,3000-Math.floor((Date.now()-R.started)/1000)),el=document.querySelector('#timer');if(el)el.textContent=`${Math.floor(sec/60)}:${String(sec%60).padStart(2,'0')}`;if(sec===0){clearInterval(timerHandle);finishTest()}}
function pickTest(i){S.run.answers[S.run.i]=i;save();renderTest()}
function testNav(d){let R=S.run;if(d>0&&R.i===44){reviewTest();return}R.i=Math.max(0,Math.min(44,R.i+d));save();renderTest()}
function finishTest(){clearInterval(timerHandle);let R=S.run,score=0,by={};C.subtopics.forEach(x=>by[x.id]={c:0,n:0});R.qs.forEach((q,i)=>{let ok=R.answers[i]===q.answer;score+=ok;by[q.sub].n++;by[q.sub].c+=ok});let result={score,bySub:by,date:new Date().toISOString()};if(R.type==='diag'){S.diag=result;C.subtopics.forEach(x=>{let z=by[x.id];if(z.n&&z.c/z.n>=.8){S.mastered[x.id]=true;S.module[x.id]={...(S.module[x.id]||{}),source:'diagnostic'}}else if(S.module[x.id]?.source==='diagnostic'){delete S.mastered[x.id];delete S.module[x.id]}})}else S.post=result;save();shell(`<section class="card hero"><div class="eyebrow">ASSESSMENT RESULTS</div><h1>${R.type==='diag'?'Diagnostic complete':'Post-assessment complete'}</h1><p class="sub">Score: <b>${score}/45 (${Math.round(score/45*100)}%)</b>.</p><button class="btn" onclick="${R.type==='diag'?"go('modules')":"report()"}">${R.type==='diag'?'See my personalized pathway':'View growth report'}</button></section>`)}

function report(){let rows=C.subtopics.map(x=>{let d=S.diag?.bySub[x.id],p=S.post?.bySub[x.id],m=S.mastered[x.id];return `<tr><td>${esc(x.domain)}</td><td>${esc(x.name)}</td><td>${d?d.c+'/'+d.n:'—'}</td><td>${m?'✓ Mastered':'Not yet'}</td><td>${p?p.c+'/'+p.n:'—'}</td></tr>`}).join('');let growth=S.diag&&S.post?S.post.score-S.diag.score:null;shell(`<section class="card report"><div class="row"><div><h1>ACT Mastery Pathway • Mastery Report</h1><p><b>Student:</b> ${esc(S.name||'________________')}</p></div><span class="spacer"></span><button class="btn no-print" onclick="window.print()">Print report</button>${S.post?'<button class="btn secondary no-print" onclick="certificate()"> Certificate</button>':''}</div><div class="grid"><div class="stat"><div class="tiny">Diagnostic</div><div class="big">${S.diag?S.diag.score+'/45':'—'}</div></div><div class="stat"><div class="tiny">Modules mastered</div><div class="big">${C.subtopics.filter(x=>S.mastered[x.id]).length}/15</div></div><div class="stat"><div class="tiny">Post-assessment</div><div class="big">${S.post?S.post.score+'/45':'—'}</div></div><div class="stat"><div class="tiny">Raw-score growth</div><div class="big">${growth===null?'—':(growth>=0?'+':'')+growth}</div></div></div><h2>Subtopic detail</h2><table><thead><tr><th>Domain</th><th>Subtopic</th><th>Diagnostic</th><th>Status</th><th>Post</th></tr></thead><tbody>${rows}</tbody></table><p class="tiny">Mastery rule: ≥80%. Diagnostic has 3 items per subtopic, so 3/3 is required for diagnostic pre-mastery. Module mastery checks require 4/5. Scores are instructional indicators, not official ACT scores.</p></section>`)}
function strategyAnalytics(){let a=(S.activity||[]).filter(x=>x.type==='strategy'),ok=a.filter(x=>x.correct).length;return {n:a.length,ok,pct:a.length?Math.round(ok/a.length*100):0}}
function studyPlan(){if(!S.diag){shell(`<section class="card"><h1> Personalized study plan</h1><p class="sub">Complete the diagnostic first. Your plan will prioritize the weakest unmastered subtopics and remove skills you have already demonstrated.</p><button class="btn" onclick="startTest('diag')">Begin diagnostic</button></section>`);return}let remaining=C.subtopics.filter(x=>!S.mastered[x.id]).sort((a,b)=>{let A=S.diag.bySub[a.id],B=S.diag.bySub[b.id];return A.c/A.n-B.c/B.n}),mins=remaining.reduce((n,x)=>n+(x.estimatedMinutes||18),0),weeks=Math.max(1,Math.ceil(mins/90));let rows=remaining.map((x,i)=>{let d=S.diag.bySub[x.id];return `<tr><td>${i+1}</td><td><b>${esc(x.name)}</b><br><span class="tiny">${esc(x.domain)}</span></td><td>${d.c}/${d.n}</td><td>${x.estimatedMinutes||18} min</td><td><button class="btn secondary" onclick="openModule('${x.id}')">Open</button></td></tr>`}).join('');shell(`<section class="card hero"><div class="eyebrow">DATA-DRIVEN PLAN</div><h1> ${esc(S.name||'Your')} study plan</h1><p class="sub">${remaining.length?`${remaining.length} modules remain • about ${mins} focused minutes • approximately ${weeks} week${weeks===1?'':'s'} at 90 minutes/week.`:'All instructional modules are mastered. You are ready for the post-assessment.'}</p></section><section class="card"><h2>Recommended sequence</h2>${remaining.length?`<table><thead><tr><th>Priority</th><th>Subtopic</th><th>Diagnostic</th><th>Est. time</th><th></th></tr></thead><tbody>${rows}</tbody></table>`:`<button class="btn" onclick="startTest('post')">Begin post-assessment</button>`}</section><section class="card"><h2>Suggested weekly routine</h2><div class="grid"><div class="callout"><b>Session A • Learn</b><span>Worked example + ACT lens + guided strategy practice.</span></div><div class="callout"><b>Session B • Retrieve</b><span>Return without notes and complete the 5-item mastery check.</span></div><div class="callout"><b>Session C • Spiral</b><span>Review one mastered module plus the next priority skill.</span></div></div></section>`)}
function resources(){let formulas=[['Percent','part = percent × whole'],['Slope','m = (y₂ − y₁)/(x₂ − x₁)'],['Midpoint','((x₁+x₂)/2, (y₁+y₂)/2)'],['Distance','√((x₂−x₁)² + (y₂−y₁)²)'],['Pythagorean theorem','a² + b² = c²'],['Rectangle','A = lw • P = 2l + 2w'],['Triangle area','A = ½bh'],['Circle','C = 2πr • A = πr²'],['Rectangular prism','V = lwh'],['Cylinder','V = πr²h'],['Polygon interior sum','(n − 2)180°'],['Trig','sin = O/H • cos = A/H • tan = O/A'],['Quadratic formula','x = (−b ± √(b²−4ac))/(2a)'],['Probability','favorable outcomes / total outcomes']];shell(`<section class="card hero"><div class="eyebrow">STUDENT TOOLKIT</div><h1> ACT Math quick reference</h1><p class="sub">A concise reference for learning and review. Do not use it during a diagnostic, mastery check, or post-assessment unless your testing plan explicitly allows references.</p></section><section class="card"><div class="row"><div><h2>Formula cards</h2><p class="tiny">Select a card to reveal the formula. Select it again to return to the topic.</p></div></div><div class="formulaCardGrid">${formulas.map(([a,b],i)=>`<button class="formulaCard" type="button" aria-pressed="false" aria-label="${esc(a)} formula card. Select to reveal formula." onclick="flipFormula(this)"><span class="formulaCardInner"><span class="formulaFace formulaFront"><span class="formulaIndex">${String(i+1).padStart(2,'0')}</span><b>${esc(a)}</b><span class="formulaPrompt">Reveal formula</span></span><span class="formulaFace formulaBack"><span class="formulaLabel">FORMULA</span><b>${esc(a)}</b><span class="formulaExpression">${esc(b)}</span><span class="formulaPrompt">Return to topic</span></span></span></button>`).join('')}</div></section><section class="card"><div class="row"><div><h2>Strategy cards</h2><p class="tiny">Select a card to reveal the strategy. Select it again to return to the topic.</p></div></div><div class="strategyGrid">${C.subtopics.map((x,i)=>`<button class="strategyCard" type="button" aria-pressed="false" aria-label="${esc(x.name)} strategy card. Select to reveal strategy." onclick="flipStrategy(this)"><span class="strategyCardInner"><span class="strategyFace strategyFront"><span class="strategyIndex">${String(i+1).padStart(2,'0')}</span><b>${esc(x.name)}</b><small>${esc(x.domain)}</small><span class="strategyPrompt">Reveal strategy</span></span><span class="strategyFace strategyBack"><span class="strategyLabel">STRATEGY</span><b>${esc(x.name)}</b><span>${esc(x.strategy[0])}</span><span class="strategyPrompt">Return to topic</span></span></span></button>`).join('')}</div></section><section class="card"><h2>ACT habits that transfer</h2><div class="grid"><div class="callout"><b>Translate before calculating</b><span>Write what the question is asking for and attach units.</span></div><div class="callout"><b>Estimate first</b><span>A rough range can eliminate implausible answer choices.</span></div><div class="callout"><b>Use answer choices strategically</b><span>Backsolve when choices are numeric and direct algebra is cumbersome.</span></div><div class="callout"><b>Move, mark, return</b><span>Flag a time-consuming item and protect time for accessible questions.</span></div><div class="callout"><b>Check representation</b><span>Tables, graphs, diagrams, and equations each encode different information.</span></div><div class="callout"><b>Calculator with purpose</b><span>Use it to reduce arithmetic load—not to replace mathematical setup.</span></div></div></section>`)}
function flipStrategy(card){let flipped=card.classList.toggle('flipped');card.setAttribute('aria-pressed',flipped?'true':'false');card.setAttribute('aria-label',flipped?'Strategy revealed. Select to return to the topic.':'Strategy card. Select to reveal strategy.')}
function flipFormula(card){let flipped=card.classList.toggle('flipped');card.setAttribute('aria-pressed',flipped?'true':'false');let topic=card.querySelector('b')?.textContent||'Formula';card.setAttribute('aria-label',flipped?`${topic} formula revealed. Select to return to the topic.`:`${topic} formula card. Select to reveal formula.`)}
function brainBreak(){let cards=[['y = mx + b','slope-intercept form'],['a² + b² = c²','right triangles'],['sin θ = O/H','sine ratio'],['A = πr²','circle area'],['P(A)','probability notation'],['f(x)','function output']];cards=shuffle(cards,rng(S.seed++));shell(`<section class="card hero"><div class="eyebrow">RETRIEVAL PRACTICE</div><h1>Two-minute brain break</h1><p class="sub">Match each expression to its meaning aloud or on scratch paper. This is retrieval practice—not a graded assessment.</p></section><section class="card"><div class="matchGrid">${cards.map(([a,b])=>`<div class="formula"><b>${a}</b><span>${b}</span></div>`).join('')}</div><button class="btn" onclick="go('modules')">Back to my pathway →</button></section>`)}
function certificate(){if(!S.post){go('home');return}let growth=S.diag?S.post.score-S.diag.score:0;shell(`<section class="certificate card"><div class="certBorder"><div class="eyebrow">CERTIFICATE OF COMPLETION</div><h1>ACT Mastery Pathway</h1><p>This certifies that</p><div class="certName">${esc(S.name||'Student')}</div><p>completed the ACT Math preparation curriculum, demonstrated mastery across all <b>15 subtopics</b>, and completed the post-assessment.</p><div class="certStats"><span>Diagnostic <b>${S.diag?.score??'—'}/45</b></span><span>Post <b>${S.post.score}/45</b></span><span>Growth <b>${growth>=0?'+':''}${growth}</b></span></div><p class="tiny">Completed ${new Date(S.post.date).toLocaleDateString()} • Instructional curriculum; not an official ACT score report.</p></div><div class="row no-print"><button class="btn" onclick="window.print()">Print certificate</button><button class="btn secondary" onclick="report()">View mastery report</button></div></section>`)}
function showDataTools(){shell(`<section class="card"><h1>Save / load student progress</h1><p class="sub">GitHub Pages is a static host, so this version stores progress in this browser. Exporting creates a portable text backup students can save; importing restores it on another device.</p><div class="row"><button class="btn" onclick="exportData()">Export progress</button><button class="btn secondary" onclick="document.querySelector('#imp').click()">Import progress</button><input id="imp" type="file" accept="application/json" hidden onchange="importData(this.files[0])"><button class="btn secondary" onclick="resetData()">Reset</button></div></section>`)}
function exportData(){let b=new Blob([JSON.stringify(S,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=`act-math-progress-${(S.name||'student').replace(/\W+/g,'-')}.json`;a.click();URL.revokeObjectURL(a.href)}
function importData(f){let r=new FileReader();r.onload=()=>{try{S=JSON.parse(r.result);save();go('home')}catch(e){alert('That file could not be read.')}};r.readAsText(f)}
function resetData(){
  if(!confirm('Reset all student progress on this browser? This cannot be undone.')) return;
  // Clear every key created by current and earlier ACT Mastery/Math Pathways builds.
  try {
    Object.keys(localStorage).forEach(k=>{
      const n=k.toLowerCase();
      if(n.includes('actmasterypathway') || n.includes('actmathpathways') || n.includes('act-math') || n.includes('act_math')) localStorage.removeItem(k);
    });
    [KEY,...OLD_KEYS].forEach(k=>localStorage.removeItem(k));
    sessionStorage.clear();
  } catch(e) {}
  // Replace in-memory state too, so reset works even if storage/reload is cached or blocked.
  S={name:'',view:'home',diag:null,mastered:{},module:{},post:null,seed:11,achievements:{},bookmarks:[],activity:[],settings:{reducedMotion:false}};
  // Do not save here: a truly fresh visit should have no progress record until the student acts.
  render();
  alert('Progress has been reset.');
}
function render(){clearInterval(timerHandle);if(S.view==='modules')modules();else if(S.view==='module'&&S.current)renderModule();else if(S.view==='course')courseMap();else if(S.view==='instructor'&&sessionStorage.getItem('ampStaff')==='1')instructorView();else home()}
render();
